#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define MLX90614_I2C_ADDR 0x5a
#define MLX90614_REG_AMBIENT_TEMP 0x06
#define MLX90614_REG_OBJECT_TEMP 0x07

int main(int argc, char *argv[]) {
    int fd;
    char *filename = "/dev/i2c-1";
    if ((fd = open(filename, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open the bus. %s\n", strerror(errno));
        exit(1);
    }
    if (ioctl(fd, I2C_SLAVE, MLX90614_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave. %s\n", strerror(errno));
        exit(1);
    }
    while (1) {
        char buf[2];
        if (read(fd, buf, 2) != 2) {
            fprintf(stderr, "Failed to read from the i2c bus. %s\n", strerror(errno));
            exit(1);
        }
        int16_t temp = (buf[0] << 8) | buf[1];
        printf("%.2f\n", temp * 0.02 - 273.15);
        sleep(5);
    }
    return 0;
}

#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>

static struct gpiod_line *gpio_line;

void gpio_cleanup(int signum)
{
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpiod_line_get_chip(gpio_line));
    exit(0);
}

int main(int argc, char *argv[])
{
    struct gpiod_chip *chip;
    struct gpiod_line_request_config line_config;
    int ret;

    signal(SIGINT, gpio_cleanup);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open chip\n");
        return 1;
    }

    line_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    line_config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    line_config.default_values[0] = 0;
    line_config.consumer = "my-consumer";

    gpio_line = gpiod_chip_get_line(chip, 4);
    if (!gpio_line) {
        fprintf(stderr, "Failed to get line\n");
        return 1;
    }

    ret = gpiod_line_request(gpio_line, &line_config, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line\n");
        return 1;
    }

    ret = gpiod_line_set_value(gpio_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set line value\n");
        return 1;
    }

    printf("GPIO 4 set to 1\n");

    ret = gpiod_line_set_value(gpio_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set line value\n");
        return 1;
    }

    printf("GPIO 4 set to 0\n");

    gpiod_line_release(gpio_line);
    gpiod_chip_close(chip);

    return 0;
}

