#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

int main(int argc, char *argv[])
{
    int gpio = 18;
    int freq = 1000;
    int duty = 500;
    int range = 1000;
    int err;

    if ((err = gpioInitialise()) < 0)
    {
        fprintf(stderr, "pigpio initialisation failed: %d\n", err);
        return 1;
    }

    if ((err = gpioSetMode(gpio, PI_OUTPUT)) < 0)
    {
        fprintf(stderr, "gpioSetMode failed: %d\n", err);
        return 1;
    }

    if ((err = gpioSetPWMfrequency(gpio, freq)) < 0)
    {
        fprintf(stderr, "gpioSetPWMfrequency failed: %d\n", err);
        return 1;
    }

    if ((err = gpioSetPWMrange(gpio, range)) < 0)
    {
        fprintf(stderr, "gpioSetPWMrange failed: %d\n", err);
        return 1;
    }

    if ((err = gpioPWM(gpio, duty)) < 0)
    {
        fprintf(stderr, "gpioPWM failed: %d\n", err);
        return 1;
    }

    while (1)
    {
        printf("gpio=%d, freq=%d, duty=%d, range=%d\n", gpio, freq, duty, range);
        gpioSleep(PI_TIME_RELATIVE, 500, 0);
    }

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIG_GPIO 17
#define ECHO_GPIO 27

int main(int argc, char *argv[])
{
    struct gpiod_chip *chip;
    struct gpiod_line *trig, *echo;
    struct gpiod_line_request req;
    struct gpiod_line_event event;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open chip\n");
        return 1;
    }

    req.request_type = GPIOD_LINE_REQUEST_EVENT_RISING_EDGE;
    req.consumer = "echo";
    req.lineoffsets[0] = TRIG_GPIO;
    req.lineoffsets[1] = ECHO_GPIO;
    req.lines = 2;
    req.flags = 0;

    ret = gpiod_chip_request_lines(chip, &req);
    if (ret < 0) {
        fprintf(stderr, "Failed to request lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    trig = gpiod_chip_get_line(chip, TRIG_GPIO);
    echo = gpiod_chip_get_line(chip, ECHO_GPIO);

    ret = gpiod_line_request_event(trig, GPIOD_LINE_REQUEST_EVENT_RISING_EDGE);
    if (ret < 0) {
        fprintf(stderr, "Failed to request event\n");
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        ret = gpiod_line_event_wait(trig, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for event\n");
            gpiod_chip_close(chip);
            return 1;
        }

        ret = gpiod_line_event_wait(echo, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for event\n");
            gpiod_chip_close(chip);
            return 1;
        }

        printf("Echo: %ld\n", event.ts.tv_sec);
    }

    gpiod_chip_close(chip);
    return 0;
}

