#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_ADDR 0x40
#define I2C_BUS "/dev/i2c-1"

int main(int argc, char *argv[]) {
    int fd;
    int rc;
    char buf[2];
    float temp;
    float humidity;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    rc = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (rc < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        return 1;
    }

    while (1) {
        buf[0] = 0xE0;
        rc = write(fd, buf, 1);
        if (rc != 1) {
            fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
            return 1;
        }

        rc = read(fd, buf, 2);
        if (rc != 2) {
            fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
            return 1;
        }

        temp = (buf[0] * 256 + buf[1]) / 65536.0 * 175.72 - 46.85;
        printf("Temperature: %.2f\n", temp);

        buf[0] = 0xE5;
        rc = write(fd, buf, 1);
        if (rc != 1) {
            fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
            return 1;
        }

        rc = read(fd, buf, 2);
        if (rc != 2) {
            fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
            return 1;
        }

        humidity = (buf[0] * 256 + buf[1]) / 65536.0 * 125 - 6;
        printf("Humidity: %.2f\n", humidity);

        sleep(5);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_ADDR 0x48
#define I2C_BUS "/dev/i2c-1"

int main(int argc, char *argv[])
{
    int fd;
    int rc;
    char buf[3];
    int i;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    rc = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (rc < 0) {
        fprintf(stderr, "Failed to select I2C device %02x: %s\n", I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    for (i = 0; i < 3; i++) {
        buf[0] = 0x00;
        buf[1] = 0x00;
        buf[2] = 0x00;
        rc = write(fd, buf, 3);
        if (rc < 0) {
            fprintf(stderr, "Failed to write to I2C device %02x: %s\n", I2C_ADDR, strerror(errno));
            close(fd);
            return 1;
        }

        rc = read(fd, buf, 2);
        if (rc < 0) {
            fprintf(stderr, "Failed to read from I2C device %02x: %s\n", I2C_ADDR, strerror(errno));
            close(fd);
            return 1;
        }

        printf("Reading %d: %02x%02x\n", i, buf[0], buf[1]);
        sleep(1);
    }

    close(fd);
    return 0;
}

