#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIG_GPIO 17
#define ECHO_GPIO 18

int main(int argc, char *argv[])
{
    struct gpiod_chip *chip;
    struct gpiod_line *trig, *echo;
    struct gpiod_line_request req;
    struct gpiod_line_event event;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    req.request_type = GPIOD_LINE_REQUEST_EVENT_RISING_EDGE;
    req.consumer = "echo";
    req.lineoffsets[0] = TRIG_GPIO;
    req.lineoffsets[1] = ECHO_GPIO;
    req.lines = 2;
    req.flags = 0;

    ret = gpiod_chip_request_lines(chip, &req);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    trig = gpiod_chip_get_line(chip, TRIG_GPIO);
    echo = gpiod_chip_get_line(chip, ECHO_GPIO);

    ret = gpiod_line_request_event(trig, GPIOD_LINE_REQUEST_EVENT_RISING_EDGE);
    if (ret < 0) {
        fprintf(stderr, "Failed to request event on trigger line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_event(echo, GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE);
    if (ret < 0) {
        fprintf(stderr, "Failed to request event on echo line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        ret = gpiod_line_event_wait(echo, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for event\n");
            gpiod_chip_close(chip);
            return 1;
        }

        ret = gpiod_line_event_wait(trig, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for event\n");
            gpiod_chip_close(chip);
            return 1;
        }

        printf("Echo: %ld\n", event.ts.tv_sec * 1000000 + event.ts.tv_nsec / 1000);
    }

    gpiod_chip_close(chip);
    return 0;
}

