#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define OPT3001_ADDR 0x44
#define OPT3001_REG_RESULT 0x00
#define OPT3001_REG_CONFIG 0x01

int main(int argc, char *argv[])
{
    int fd;
    int rc;
    uint16_t config;
    uint16_t result;
    uint8_t buf[2];

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    rc = ioctl(fd, I2C_SLAVE, OPT3001_ADDR);
    if (rc < 0) {
        perror("ioctl");
        exit(1);
    }

    config = 0x1000;
    buf[0] = OPT3001_REG_CONFIG;
    buf[1] = config & 0xff;
    buf[2] = (config >> 8) & 0xff;
    rc = write(fd, buf, 3);
    if (rc != 3) {
        perror("write");
        exit(1);
    }

    rc = read(fd, buf, 2);
    if (rc != 2) {
        perror("read");
        exit(1);
    }

    result = buf[0] | (buf[1] << 8);
    printf("result: 0x%04x\n", result);

    close(fd);

    return 0;
}

