static struct gpiod_line *line;

void cleanup(int signum)
{
    gpiod_line_release(line);
    gpiod_chip_close(gpiod_line_get_chip(line));
    exit(0);
}

int main(int argc, char *argv[])
{
    struct gpiod_chip *chip;
    struct gpiod_line_request_config line_config;
    int ret;

    signal(SIGINT, cleanup);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    line_config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    line_config.default_values[0] = 0;
    line_config.consumer = "my-consumer";

    line = gpiod_chip_get_line(chip, 4);
    if (!line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    ret = gpiod_line_request(line, &line_config, 0);
    if (ret < 0) {
        perror("gpiod_line_request");
        return 1;
    }

    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        return 1;
    }

    printf("GPIO 4 set to 1\n");

    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        return 1;
    }

    printf("GPIO 4 set to 0\n");

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

