#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <sys/time.h>
#include <time.h>

#define MAX_PATH 256
#define MAX_LINE 256

int main(int argc, char *argv[])
{
    int fd;
    char path[MAX_PATH];
    char line[MAX_LINE];
    int len;
    int temp;
    int i;
    int ret;
    int status;
    struct timeval tv;
    struct timeval tv_start;
    struct timeval tv_end;
    struct timeval tv_diff;
    struct tm *tm;
    char time_str[MAX_LINE];

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <device>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    snprintf(path, sizeof(path), "/sys/bus/w1/devices/%s/w1_slave", argv[1]);

    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        exit(EXIT_FAILURE);
    }

    gettimeofday(&tv_start, NULL);

    while (1) {
        ret = read(fd, line, sizeof(line));
        if (ret < 0) {
            fprintf(stderr, "Failed to read %s: %s\n", path, strerror(errno));
            exit(EXIT_FAILURE);
        }

        if (ret < 2) {
            fprintf(stderr, "Failed to read %s: short read\n", path);
            exit(EXIT_FAILURE);
        }

        if (line[0] != '0' || line[1] != '0') {
            fprintf(stderr, "Failed to read %s: invalid data\n", path);
            exit(EXIT_FAILURE);
        }

        len = strlen(line);
        if (len < 38) {
            fprintf(stderr, "Failed to read %s: short data\n", path);
            exit(EXIT_FAILURE);
        }

        if (line[len - 3] != 'Y') {
            fprintf(stderr, "Failed to read %s: CRC error\n", path);
            exit(EXIT_FAILURE);
        }

        temp = 0;
        for (i = 0; i < 12; i++) {
            temp *= 10;
            temp += line[2 + i] - '0';
        }

        temp /= 1000;

        gettimeofday(&tv_end, NULL);
        timersub(&tv_end, &tv_start, &tv_diff);
        tv = tv_diff;
        tm = localtime(&tv.tv_sec);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);

        printf("%s.%06ld: %d\n", time_str, tv.tv_usec, temp);

        sleep(5);
    }

    close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x40
#define I2C_REG_TEMP 0xE3
#define I2C_REG_HUMID 0xE5

int main(int argc, char *argv[]) {
    int fd;
    int ret;
    char buf[3];

    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    ret = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        return 1;
    }

    while (1) {
        ret = write(fd, &I2C_REG_TEMP, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
            return 1;
        }

        ret = read(fd, buf, 3);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
            return 1;
        }

        int temp = (buf[0] << 8) | buf[1];
        temp = (temp * 175.72) / 65536.0 - 46.85;
        printf("Temperature: %.2f C\n", temp);

        ret = write(fd, &I2C_REG_HUMID, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
            return 1;
        }

        ret = read(fd, buf, 3);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
            return 1;
        }

        int humid = (buf[0] << 8) | buf[1];
        humid = (humid * 125.0) / 65536.0 - 6.0;
        printf("Humidity: %.2f %%\n", humid);

        sleep(60);
    }

    close(fd);
    return 0;
}

