static void ssd1306_command(uint8_t c)
{
    uint8_t control = 0x00;
    if (write(fd, &control, 1) != 1) {
        perror("write control");
        exit(1);
    }
    if (write(fd, &c, 1) != 1) {
        perror("write command");
        exit(1);
    }
}

static void ssd1306_data(uint8_t c)
{
    uint8_t control = 0x40;
    if (write(fd, &control, 1) != 1) {
        perror("write control");
        exit(1);
    }
    if (write(fd, &c, 1) != 1) {
        perror("write data");
        exit(1);
    }
}

static void ssd1306_init(void)
{
    ssd1306_command(SSD1306_DISPLAYOFF);
    ssd1306_command(SSD1306_SETDISPLAYCLOCKDIV);
    ssd1306_command(0x80);
    ssd1306_command(SSD1306_SETMULTIPLEX);
    ssd1306_command(0x3F);
    ssd1306_command(SSD1306_SETDISPLAYOFFSET);
    ssd1306_command(0x0);
    ssd1306_command(SSD1306_SETSTARTLINE | 0x0);
    ssd1306_command(SSD1306_CHARGEPUMP);
    ssd1306_command(0x14);
    ssd1306_command(SSD1306_MEMORYMODE);
    ssd1306_command(0x00);
    ssd1306_command(SSD1306_SEGREMAP | 0x1);
    ssd1306_command(SSD1306_COMSCANDEC);
    ssd1306_command(SSD1306_SETCOMPINS);
    ssd1306_command(0x12);
    ssd1306_command(SSD1306_SETCONTRAST);
    ssd1306_command(0xCF);
    ssd1306_command(SSD1306_SETPRECHARGE);
    ssd1306_command(0xF1);
    ssd1306_command(SSD1306_SETVCOMDETECT);
    ssd1306_command(0x40);
    ssd1306_command(SSD1306_DISPLAYALLON_RESUME);
    ssd1306_command(SSD1306_NORMALDISPLAY);
    ssd1306_command(SSD1306_DISPLAYON);
}

static void ssd1306_clear(void)
{
    uint8_t i, j;
    for (i = 0; i < SSD1306_HEIGHT / 8; i++) {
        ssd1306_command(SSD1306_PAGEADDR);
        ssd1306_command(i);
        ssd1306_command(0);
        ssd1306_command(SSD1306_WIDTH - 1);
        for (j = 0; j < SSD1306_WIDTH; j++) {
            ssd1306_data(0x00);
        }
    }
}

static void ssd1306_display(void)
{
    uint8_t i, j;
    for (i = 0; i < SSD1306_HEIGHT / 8; i++) {
        ssd1306_command(SSD1306_PAGEADDR);
        ssd1306_command(i);
        ssd1306_command(0);
        ssd1306_command(SSD1306_WIDTH - 1);
        for (j = 0; j < SSD1306_WIDTH; j++) {
            ssd1306_data(0x00);
        }
    }
}

static void ssd1306_set_pixel(uint8_t x, uint8_t y, uint8_t color)
{
    if (x >= SSD1306_WIDTH || y >= SSD1306_HEIGHT) {
        return;
    }
    uint8_t page = y / 8;
    uint8_t bit = y % 8;
    uint8_t mask = 1 << bit;
    if (color) {
        ssd1306_buffer[page * SSD1306_WIDTH + x] |= mask;
    } else {
        ssd1306_buffer[page * SSD1306_WIDTH + x] &= ~mask;
    }
}

static void ssd1306_draw_char(uint8_t x, uint8_t y, char c, uint8_t color)
{
    uint8_t i, j;
    for (i = 0; i < 5; i++) {
        uint8_t data = font5x7[c * 5 + i];
        for (j = 0; j < 8; j++) {
            if (data & 0x1) {
                ssd1306_set_pixel(x + i, y + j, color);
            }
            data >>= 1;
        }
    }
}

static void ssd1306_draw_string(uint8_t x, uint8_t y, char *s, uint8_t color)
{
    while (*s) {
        ssd1306_draw_char(x, y, *s, color);
        x += 6;
        s++;
    }
}

static void ssd1306_draw_int(uint8_t x, uint8_t y, int i, uint8_t color)
{
    char buf[16];
    sprintf(buf, "%d", i);
    ssd1306_draw_string(x, y, buf, color);
}

static void ssd1306_draw_float(uint8_t x, uint8_t y, float f, uint8_t color)
{
    char buf[16];
    sprintf(buf, "%.2f", f);
    ssd1306_draw_string(x, y, buf, color);
}

static void ssd1306_draw_line(uint8_t x0, uint8_t y0, uint8_t x1, uint8_t y1, uint8_t color)
{
    int dx = abs(x1 - x0), sx = x0 < x1 ? 1 : -1;
    int dy = abs(y1 - y0), sy = y0 < y1 ? 1 : -1;
    int err = (dx > dy ? dx : -dy) / 2, e2;
    for (;;) {
        ssd1306_set_pixel(x0, y0, color);
        if (x0 == x1 && y0 == y1) {
            break;
        }
        e2 = err;
        if (e2 > -dx) {
            err -= dy;
            x0 += sx;
        }
        if (e2 < dy) {
            err += dx;
            y0 += sy;
        }
    }
}

static void ssd1306_draw_rect(uint8_t x, uint8_t y, uint8_t w, uint8_t h, uint8_t color)
{
    ssd1306_draw_line(x, y, x + w, y, color);
    ssd1306_draw_line(x, y, x, y + h, color);
    ssd1306_draw_line(x + w, y, x + w, y + h, color);
    ssd1306_draw_line(x, y + h, x + w, y + h, color);
}

static void ssd1306_draw_circle(uint8_t x0, uint8_t y0, uint8_t r, uint8_t color)
{
    int x = -r, y = 0, err = 2 - 2 * r;
    do {
        ssd1306_set_pixel(x0 - x, y0 + y, color);
