#define GPIO_8 8
#define GPIO_9 9
#define GPIO_11 11
#define GPIO_18 18

#define PWM_FREQ 1000
#define PWM_RANGE 1000

#define PWM_DUTY_CYCLE_8 500
#define PWM_DUTY_CYCLE_9 250
#define PWM_DUTY_CYCLE_11 750
#define PWM_DUTY_CYCLE_18 100

void sig_handler(int signo)
{
    if (signo == SIGINT)
    {
        printf("received SIGINT\n");
        gpioTerminate();
        exit(0);
    }
}

int main(void)
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_8, PI_OUTPUT);
    gpioSetMode(GPIO_9, PI_OUTPUT);
    gpioSetMode(GPIO_11, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);

    gpioSetPWMfrequency(GPIO_8, PWM_FREQ);
    gpioSetPWMfrequency(GPIO_9, PWM_FREQ);
    gpioSetPWMfrequency(GPIO_11, PWM_FREQ);
    gpioSetPWMfrequency(GPIO_18, PWM_FREQ);

    gpioSetPWMrange(GPIO_8, PWM_RANGE);
    gpioSetPWMrange(GPIO_9, PWM_RANGE);
    gpioSetPWMrange(GPIO_11, PWM_RANGE);
    gpioSetPWMrange(GPIO_18, PWM_RANGE);

    gpioPWM(GPIO_8, PWM_DUTY_CYCLE_8);
    gpioPWM(GPIO_9, PWM_DUTY_CYCLE_9);
    gpioPWM(GPIO_11, PWM_DUTY_CYCLE_11);
    gpioPWM(GPIO_18, PWM_DUTY_CYCLE_18);

    signal(SIGINT, sig_handler);

    while (1)
    {
        printf("GPIO 8: %d\n", PWM_DUTY_CYCLE_8);
        printf("GPIO 9: %d\n", PWM_DUTY_CYCLE_9);
        printf("GPIO 11: %d\n", PWM_DUTY_CYCLE_11);
        printf("GPIO 18: %d\n", PWM_DUTY_CYCLE_18);
        sleep(1);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIG 17
#define ECHO 23
#define LED 24

int main(void)
{
    struct gpiod_chip *chip;
    struct gpiod_line *trig, *echo, *led;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    trig = gpiod_chip_get_line(chip, TRIG);
    if (!trig) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    echo = gpiod_chip_get_line(chip, ECHO);
    if (!echo) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    led = gpiod_chip_get_line(chip, LED);
    if (!led) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(trig, "trig", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(echo, "echo");
    if (ret < 0) {
        perror("gpiod_line_request_input");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(led, "led", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        exit(EXIT_FAILURE);
    }

    while (1) {
        gpiod_line_set_value(trig, 1);
        usleep(10);
        gpiod_line_set_value(trig, 0);

        while (gpiod_line_get_value(echo) == 0);
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);

        while (gpiod_line_get_value(echo) == 1);
        clock_gettime(CLOCK_MONOTONIC, &end);

        double elapsed = (end.tv_sec - start.tv_sec);
        elapsed += (end.tv_nsec - start.tv_nsec) / 1000000000.0;
        double distance = (elapsed * 340.29) / 2;

        if (distance < 10)
            gpiod_line_set_value(led, 1);
        else
            gpiod_line_set_value(led, 0);

        sleep(0.2);
    }

    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_line_release(led);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
