int main(int argc, char *argv[])
{
    if (argc != 4)
    {
        printf("Usage: %s <red> <green> <blue>\n", argv[0]);
        return 1;
    }

    int red = atoi(argv[1]);
    int green = atoi(argv[2]);
    int blue = atoi(argv[3]);

    if (gpioInitialise() < 0)
    {
        printf("pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIN, PI_OUTPUT);

    while (1)
    {
        gpioWrite(PIN, red);
        gpioDelay(DELAY);
        gpioWrite(PIN, green);
        gpioDelay(DELAY);
        gpioWrite(PIN, blue);
        gpioDelay(DELAY);
    }

    gpioTerminate();
    return 0;
}

