    uint8_t id;
    uint8_t temp[3];
    uint8_t hum[2];
    uint8_t pres[3];
    int32_t temp_raw;
    uint32_t hum_raw;
    uint32_t pres_raw;
    float temp_c;
    float hum_rh;
    float pres_pa;

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

