        perror("read");
        exit(EXIT_FAILURE);
    }

    if (id != 0x60) {
        fprintf(stderr, "BME280 not found\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        if (read(fd, temp, 3) != 3) {
            perror("read");
            exit(EXIT_FAILURE);
        }

