            perror("read");
            exit(EXIT_FAILURE);
        }

        temp_raw = (temp[0] << 12) | (temp[1] << 4) | (temp[2] >> 4);
        temp_c = temp_raw / 100.0;

        hum_raw = (hum[0] << 8) | hum[1];
        hum_rh = hum_raw / 1024.0;

        pres_raw = (pres[0] << 12) | (pres[1] << 4) | (pres[2] >> 4);
        pres_pa = pres_raw / 256.0;

        printf("temp: %.2f C\n", temp_c);
        printf("hum: %.2f %%\n", hum_rh);
        printf("pres: %.2f Pa\n", pres_pa);

        sleep(5);
    }

    close(fd);

    return 0;
}

