#define I2C_CONFIG_MUX_DIFF_0_1 0x4000
#define I2C_CONFIG_PGA_6_144V 0x0000
#define I2C_CONFIG_MODE_CONTINUOUS 0x0000
#define I2C_CONFIG_DR_128SPS 0x0080
#define I2C_CONFIG_COMP_QUE_1CONV 0x0003

int fd;

void cleanup(int signum) {
    if (fd != -1) {
        close(fd);
    }
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    fd = open(I2C_BUS, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) == -1) {
        fprintf(stderr, "Failed to select I2C device: %s\n", strerror(errno));
        close(fd);
        exit(1);
    }

    uint16_t config = I2C_CONFIG_OS | I2C_CONFIG_MUX_DIFF_0_1 | I2C_CONFIG_PGA_6_144V | I2C_CONFIG_MODE_CONTINUOUS | I2C_CONFIG_DR_128SPS | I2C_CONFIG_COMP_QUE_1CONV;
    if (write(fd, &config, 2) != 2) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        close(fd);
        exit(1);
    }

    uint16_t lo, hi;
    while (1) {
        if (read(fd, &lo, 2) != 2) {
            fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
            close(fd);
            exit(1);
        }
        if (read(fd, &hi, 2) != 2) {
            fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
            close(fd);
            exit(1);
        }
        uint16_t value = (hi << 8) | lo;
        float voltage = (float)value * 6.144 / 32768;
        printf("%f\n", voltage);
        usleep(200000);
    }

    return 0;
}

