int fd;

void lcd_init(void) {
    // Initialise display
    lcd_command(LCD_FUNCTIONSET | LCD_2LINE | LCD_5x8DOTS | LCD_4BITMODE);
    usleep(4500);
    lcd_command(LCD_FUNCTIONSET | LCD_2LINE | LCD_5x8DOTS | LCD_4BITMODE);
    usleep(4500);
    lcd_command(LCD_FUNCTIONSET | LCD_2LINE | LCD_5x8DOTS | LCD_4BITMODE);
    usleep(150);
    lcd_command(LCD_FUNCTIONSET | LCD_2LINE | LCD_5x8DOTS | LCD_4BITMODE);

    // Turn the display on with no cursor or blinking default
    lcd_command(LCD_DISPLAYCONTROL | LCD_DISPLAYON);

    // Clear it off
    lcd_command(LCD_CLEARDISPLAY);
    usleep(2000);

    // Initialize to default text direction (for romance languages)
    lcd_command(LCD_ENTRYMODESET | LCD_ENTRYLEFT);

    // Turn on the backlight
    lcd_command(LCD_DISPLAYCONTROL | LCD_DISPLAYON | LCD_BACKLIGHT);
}

void lcd_command(unsigned char cmd) {
    // Send bit7-4 firstly
    lcd_write(cmd & 0xF0, 0);
    lcd_pulse_enable(cmd & 0xF0);

    // Send bit3-0 secondly
    lcd_write((cmd << 4) & 0xF0, 0);
    lcd_pulse_enable((cmd << 4) & 0xF0);
}

void lcd_write(unsigned char data, unsigned char mode) {
    // Send the high 4 bits
    write_byte(mode | (data & 0xF0));

    // Send the low 4 bits
    write_byte(mode | ((data << 4) & 0xF0));
}

void lcd_pulse_enable(unsigned char data) {
    // Send a pulse on Enable Pin
    write_byte(data | En);
    usleep(1);
    write_byte(data & ~En);
    usleep(50);
}

void write_byte(unsigned char data) {
    // Write a byte to the I2C device
    if (write(fd, &data, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        exit(1);
    }
}

