#include <errno.h>
#include <string.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x68
#define I2C_REG_ACCEL_XOUT_H 0x3B
#define I2C_REG_ACCEL_XOUT_L 0x3C
#define I2C_REG_ACCEL_YOUT_H 0x3D
#define I2C_REG_ACCEL_YOUT_L 0x3E
#define I2C_REG_ACCEL_ZOUT_H 0x3F
#define I2C_REG_ACCEL_ZOUT_L 0x40

int main(int argc, char *argv[]) {
    int fd;
    int rc;
    char buf[16];
    int x, y, z;

    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    rc = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (rc < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        return 1;
    }

    for (int i = 0; i < 100; i++) {
        rc = read(fd, buf, 1);
        if (rc < 0) {
            fprintf(stderr, "Failed to read I2C register: %s\n", strerror(errno));
            return 1;
        }

        rc = write(fd, &I2C_REG_ACCEL_XOUT_H, 1);
        if (rc < 0) {
            fprintf(stderr, "Failed to write I2C register: %s\n", strerror(errno));
            return 1;
        }

        rc = read(fd, buf, 2);
        if (rc < 0) {
            fprintf(stderr, "Failed to read I2C register: %s\n", strerror(errno));
            return 1;
        }

        x = (buf[0] << 8) | buf[1];

        rc = write(fd, &I2C_REG_ACCEL_YOUT_H, 1);
        if (rc < 0) {
            fprintf(stderr, "Failed to write I2C register: %s\n", strerror(errno));
            return 1;
        }

        rc = read(fd, buf, 2);
        if (rc < 0) {
            fprintf(stderr, "Failed to read I2C register: %s\n", strerror(errno));
            return 1;
        }

        y = (buf[0] << 8) | buf[1];

        rc = write(fd, &I2C_REG_ACCEL_ZOUT_H, 1);
        if (rc < 0) {
            fprintf(stderr, "Failed to write I2C register: %s\n", strerror(errno));
            return 1;
        }

        rc = read(fd, buf, 2);
        if (rc < 0) {
            fprintf(stderr, "Failed to read I2C register: %s\n", strerror(errno));
            return 1;
        }

        z = (buf[0] << 8) | buf[1];

        printf("X: %d, Y: %d, Z: %d\n", x, y, z);
    }

    close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

int main(int argc, char *argv[])
{
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, 14);
    if (!line) {
        fprintf(stderr, "Failed to get line\n");
        return 1;
    }

    ret = gpiod_line_request_output(line, "my-consumer", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line\n");
        return 1;
    }

    while (1) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line value\n");
            return 1;
        }

        printf("Line value set to 1\n");

        sleep(5);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line value\n");
            return 1;
        }

        printf("Line value set to 0\n");

        sleep(5);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <mosquitto.h>

#define I2C_ADDR 0x48
#define I2C_REG_CONFIG 0x01
#define I2C_REG_RESULT 0x00
#define I2C_CONFIG_12BIT 0x03
#define I2C_CONFIG_CONTINUOUS 0x00
#define I2C_CONFIG_SINGLE 0x01
#define I2C_CONFIG_POWERDOWN 0x02
#define I2C_CONFIG_ALERT_HIGH 0x04
#define I2C_CONFIG_ALERT_LOW 0x08
#define I2C_CONFIG_ALERT_FLAG 0x10
#define I2C_CONFIG_ALERT_POLARITY 0x20
#define I2C_CONFIG_ALERT_MODE 0x40
#define I2C_CONFIG_ALERT_CLEAR 0x80

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/temperature"

#define SENSOR_MIN 0
#define SENSOR_MAX 100

#define SLEEP_TIME 10000

int i2c_fd;
struct mosquitto *mosq;

void mqtt_connect(void)
{
    int rc;

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        exit(1);
    }

    rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc) {
        fprintf(stderr, "Error: %s\n", mosquitto_strerror(rc));
        exit(1);
    }

    rc = mosquitto_loop_start(mosq);
    if (rc) {
        fprintf(stderr, "Error: %s\n", mosquitto_strerror(rc));
        exit(1);
    }
}

void mqtt_disconnect(void)
{
    mosquitto_disconnect(mosq);
    mosquitto_loop_stop(mosq, false);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
}

void mqtt_publish(const char *payload)
{
    int rc;

    rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (rc) {
        fprintf(stderr, "Error: %s\n", mosquitto_strerror(rc));
        exit(1);
    }
}

int i2c_read(void)
{
    int rc;
    int value;

    rc = wiringPiI2CReadReg16(i2c_fd, I2C_REG_RESULT);
    if (rc < 0) {
        fprintf(stderr, "Error: %s\n", strerror(errno));
        exit(1);
    }

    value = (rc >> 4) & 0xfff;
    if (value < SENSOR_MIN || value > SENSOR_MAX) {
        fprintf(stderr, "Error: Invalid reading %d\n", value);
        exit(1);
    }

    return value;
}

void i2c_init(void)
{
    int rc;

    i2c_fd = wiringPiI2CSetup(I2C_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: %s\n", strerror(errno));
        exit(1);
    }

    rc = wiringPiI2CWriteReg8(i2c_fd, I2C_REG_CONFIG, I2C_CONFIG_12BIT | I2C_CONFIG_CONTINUOUS);
    if (rc < 0) {
        fprintf(stderr, "Error: %s\n", strerror(errno));
        exit(1);
    }
}

void i2c_deinit(void)
{
    int rc;

    rc = wiringPiI2CWriteReg8(i2c_fd, I2C_REG_CONFIG, I2C_CONFIG_POWERDOWN);
    if (rc < 0) {
        fprintf(stderr, "Error: %s\n", strerror(errno));
        exit(1);
    }
}

int main(void)
{
    int rc;
    int value;
    char payload[16];

    rc = wiringPiSetup();
    if (rc < 0) {
        fprintf(stderr, "Error: %s\n", strerror(errno));
        exit(1);
    }

    i2c_init();
    mqtt_connect();

    while (1) {
        value = i2c_read();
        snprintf(payload, sizeof(payload), "%d", value);
        mqtt_publish(payload);
        delay(SLEEP_TIME);
    }

    i2c_deinit();
    mqtt_disconnect();

    return 0;
}

