#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIG_GPIO 17
#define ECHO_GPIO 22
#define LED_GPIO 27

int main(int argc, char *argv[])
{
    struct gpiod_chip *chip;
    struct gpiod_line *trig, *echo, *led;
    struct gpiod_line_request req;
    struct gpiod_line_event event;
    int ret;
    int distance;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    req.request_type = GPIOD_LINE_REQ_EVENT_RISING_EDGE;
    req.consumer = "echo";
    req.lineoffsets[0] = TRIG_GPIO;
    req.lineoffsets[1] = ECHO_GPIO;
    req.lineoffsets[2] = LED_GPIO;
    req.flags = GPIOD_LINE_REQUEST_FLAG_NONBLOCKING;
    req.lines = 3;

    ret = gpiod_chip_request_lines(chip, &req);
    if (ret < 0) {
        perror("gpiod_chip_request_lines");
        exit(EXIT_FAILURE);
    }

    trig = gpiod_chip_get_line(chip, TRIG_GPIO);
    echo = gpiod_chip_get_line(chip, ECHO_GPIO);
    led = gpiod_chip_get_line(chip, LED_GPIO);

    gpiod_line_request_event(trig, GPIOD_LINE_REQUEST_EVENT_RISING_EDGE);
    gpiod_line_request_event(echo, GPIOD_LINE_REQUEST_EVENT_RISING_EDGE);

    while (1) {
        ret = gpiod_line_event_wait(echo, &event);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            exit(EXIT_FAILURE);
        }

        gpiod_line_set_value(trig, 1);
        usleep(10);
        gpiod_line_set_value(trig, 0);

        ret = gpiod_line_event_wait(echo, &event);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            exit(EXIT_FAILURE);
        }

        distance = event.ts.tv_nsec / 1000000;
        printf("Distance: %d mm\n", distance);

        if (distance < 1000) {
            gpiod_line_set_value(led, 1);
        } else {
            gpiod_line_set_value(led, 0);
        }

        usleep(100000);
    }

    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_line_release(led);
    gpiod_chip_close(chip);

    return 0;
}

