#include <gpiod.h>

#define TRIG 23
#define ECHO 24

int main(void)
{
    struct gpiod_chip *chip;
    struct gpiod_line *trig, *echo;
    struct gpiod_line_request req;
    struct gpiod_line_event event;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    req.request_type = GPIOD_LINE_REQ_EVENT_RISING_EDGE;
    req.flags = GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN;
    req.consumer = "echo";
    req.lineoffsets[0] = TRIG;
    req.lineoffsets[1] = ECHO;
    req.num_lines = 2;

    ret = gpiod_chip_request_lines(chip, &req);
    if (ret < 0) {
        perror("gpiod_chip_request_lines");
        exit(EXIT_FAILURE);
    }

    trig = gpiod_chip_get_line(chip, TRIG);
    echo = gpiod_chip_get_line(chip, ECHO);

    while (1) {
        ret = gpiod_line_event_wait(echo, &event);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            exit(EXIT_FAILURE);
        }

        gpiod_line_set_value(trig, 1);
        usleep(10);
        gpiod_line_set_value(trig, 0);

        printf("echo: %ld\n", event.ts.tv_sec * 1000000 + event.ts.tv_nsec / 1000);

        usleep(200000);
    }

    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

int main(int argc, char *argv[])
{
    if (gpioInitialise() < 0) return 1;
    gpioSetMode(17, PI_OUTPUT);
    gpioSetMode(18, PI_OUTPUT);
    gpioSetMode(22, PI_OUTPUT);
    gpioSetMode(23, PI_OUTPUT);
    gpioWrite(17, 1);
    gpioWrite(18, 1);
    gpioWrite(22, 1);
    gpioWrite(23, 1);
    while (1) {
        gpioWrite(17, 0);
        gpioWrite(18, 0);
        gpioWrite(22, 0);
        gpioWrite(23, 0);
        gpioWrite(17, 1);
        gpioWrite(18, 1);
        gpioWrite(22, 1);
        gpioWrite(23, 1);
        gpioDelay(100000);
    }
    gpioTerminate();
    return 0;
}

