#include <termios.h>
#include <unistd.h>

#define BAUDRATE B9600
#define MODEMDEVICE "/dev/ttyS0"
#define _POSIX_SOURCE 1
#define FALSE 0
#define TRUE 1

int main()
{
    int fd, c, res;
    struct termios oldtio, newtio;
    char buf[255];

    fd = open(MODEMDEVICE, O_RDWR | O_NOCTTY);
    if (fd < 0)
    {
        perror(MODEMDEVICE);
        exit(-1);
    }

    tcgetattr(fd, &oldtio);
    bzero(&newtio, sizeof(newtio));

    newtio.c_cflag = BAUDRATE | CRTSCTS | CS8 | CLOCAL | CREAD;
    newtio.c_iflag = IGNPAR;
    newtio.c_oflag = 0;
    newtio.c_lflag = 0;
    newtio.c_cc[VTIME] = 0;
    newtio.c_cc[VMIN] = 1;

    tcflush(fd, TCIFLUSH);
    tcsetattr(fd, TCSANOW, &newtio);

    while (1)
    {
        res = read(fd, buf, 255);
        buf[res] = 0;
        printf(":%s:%d\n", buf, res);
    }

    tcsetattr(fd, TCSANOW, &oldtio);
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_ADDR 0x68
#define I2C_BUS "/dev/i2c-1"

int main(int argc, char *argv[]) {
    int fd;
    int rc;
    uint8_t buf[14];
    int16_t ax, ay, az, gx, gy, gz;
    float axg, ayg, azg, gxds, gyds, gzds;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    rc = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (rc < 0) {
        perror("ioctl");
        exit(1);
    }

    rc = write(fd, 0x6B, 1);
    if (rc < 0) {
        perror("write");
        exit(1);
    }

    rc = write(fd, 0x00, 1);
    if (rc < 0) {
        perror("write");
        exit(1);
    }

    while (1) {
        rc = read(fd, buf, 14);
        if (rc < 0) {
            perror("read");
            exit(1);
        }

        ax = (buf[0] << 8) | buf[1];
        ay = (buf[2] << 8) | buf[3];
        az = (buf[4] << 8) | buf[5];
        gx = (buf[8] << 8) | buf[9];
        gy = (buf[10] << 8) | buf[11];
        gz = (buf[12] << 8) | buf[13];

        axg = ax / 16384.0;
        ayg = ay / 16384.0;
        azg = az / 16384.0;
        gxds = gx / 131.0;
        gyds = gy / 131.0;
        gzds = gz / 131.0;

        printf("ax=%f ay=%f az=%f gx=%f gy=%f gz=%f\n", axg, ayg, azg, gxds, gyds, gzds);

        sleep(1);
    }

    rc = close(fd);
    if (rc < 0) {
        perror("close");
        exit(1);
    }

    return 0;
}

