#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_ADDR 0x27
#define I2C_BUS "/dev/i2c-1"

int main(int argc, char *argv[]) {
    int fd;
    int i;
    int ret;
    char buf[2];

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    ret = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("ioctl");
        exit(1);
    }

    buf[0] = 0x00;
    buf[1] = 0x00;
    ret = write(fd, buf, 2);
    if (ret < 0) {
        perror("write");
        exit(1);
    }

    for (i = 0; i < 10; i++) {
        buf[0] = 0x00;
        buf[1] = i;
        ret = write(fd, buf, 2);
        if (ret < 0) {
            perror("write");
            exit(1);
        }
        sleep(1);
    }

    close(fd);
    return 0;
}

