#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

int main(int argc, char *argv[])
{
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        fprintf(stderr, "Failed to get line\n");
        return 1;
    }

    ret = gpiod_line_request_output(line, "trigger", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request output\n");
        return 1;
    }

    ret = gpiod_line_request_input(line, "echo");
    if (ret < 0) {
        fprintf(stderr, "Failed to request input\n");
        return 1;
    }

    while (1) {
        gpiod_line_set_value(line, 1);
        usleep(10);
        gpiod_line_set_value(line, 0);

        ret = gpiod_line_event_wait(line, -1);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for event\n");
            return 1;
        }

        struct gpiod_line_event event;
        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to read event\n");
            return 1;
        }

        printf("Event: %d\n", event.event_type);

        sleep(1);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

