void sig_handler(int signo)
{
    if (signo == SIGINT)
    {
        printf("received SIGINT\n");
        gpioPWM(GPIO, 0);
        gpioSetMode(GPIO, PI_INPUT);
        gpioTerminate();
        exit(0);
    }
}

int main(void)
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO, FREQ);
    gpioSetPWMrange(GPIO, 1000);
    gpioPWM(GPIO, DUTY);

    signal(SIGINT, sig_handler);

    while (1)
    {
        printf("GPIO %d: PWM %d Hz, duty cycle %d%%\n", GPIO, FREQ, DUTY);
        sleep(5);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_ADDR 0x27
#define I2C_BUS "/dev/i2c-1"

int main(int argc, char *argv[])
{
    int fd;
    int i;
    int ret;
    char buf[2];

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <value>\n", argv[0]);
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    ret = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    buf[0] = 0x00;
    buf[1] = atoi(argv[1]);
    ret = write(fd, buf, 2);
    if (ret != 2) {
        perror("write");
        close(fd);
        return 1;
    }

    close(fd);
    return 0;
}

