    if (fd < 0) {
        perror("open");
        return 1;
    }

    ret = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("ioctl");
        return 1;
    }

    ret = i2c_smbus_write_byte_data(fd, I2C_REG_PWR_MGMT_1, I2C_REG_PWR_MGMT_1_SLEEP);
    if (ret < 0) {
        perror("i2c_smbus_write_byte_data");
        return 1;
    }

    while (1) {
        ret = i2c_smbus_read_i2c_block_data(fd, I2C_REG_ACCEL_XOUT_H, 14, buf);
        if (ret < 0) {
            perror("i2c_smbus_read_i2c_block_data");
            return 1;
        }

        int16_t x = (buf[0] << 8) | buf[1];
        int16_t y = (buf[2] << 8) | buf[3];
        int16_t z = (buf[4] << 8) | buf[5];

        printf("x: %d, y: %d, z: %d\n", x, y, z);

        usleep(100000);
    }

    return 0;
}

