#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_ADDR 0x44
#define I2C_BUS "/dev/i2c-1"

int main(int argc, char *argv[]) {
    int fd;
    int err;
    char buf[2];
    float temp;
    float humidity;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    err = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (err < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    while (1) {
        buf[0] = 0x2C;
        buf[1] = 0x06;
        err = write(fd, buf, 2);
        if (err != 2) {
            fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
            close(fd);
            return 1;
        }

        usleep(100000);

        err = read(fd, buf, 6);
        if (err != 6) {
            fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
            close(fd);
            return 1;
        }

        temp = -45 + 175 * (buf[0] * 256 + buf[1]) / 65535.0;
        humidity = 100 * (buf[3] * 256 + buf[4]) / 65535.0;

        printf("Temperature: %.2f C\n", temp);
        printf("Humidity: %.2f %%\n", humidity);

        sleep(5);
    }

    close(fd);
    return 0;
}

