#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

int main(int argc, char *argv[])
{
    int gpio = 17;
    int freq = 1000;
    int duty = 500;
    int range = 1000;
    int err;

    if (argc > 1) {
        gpio = atoi(argv[1]);
    }

    if (argc > 2) {
        freq = atoi(argv[2]);
    }

    if (argc > 3) {
        duty = atoi(argv[3]);
    }

    if (argc > 4) {
        range = atoi(argv[4]);
    }

    if ((err = gpioInitialise()) < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", err);
        return 1;
    }

    if ((err = gpioSetMode(gpio, PI_OUTPUT)) < 0) {
        fprintf(stderr, "gpioSetMode failed: %d\n", err);
        return 1;
    }

    if ((err = gpioSetPWMfrequency(gpio, freq)) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed: %d\n", err);
        return 1;
    }

    if ((err = gpioSetPWMrange(gpio, range)) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed: %d\n", err);
        return 1;
    }

    if ((err = gpioPWM(gpio, duty)) < 0) {
        fprintf(stderr, "gpioPWM failed: %d\n", err);
        return 1;
    }

    printf("gpio=%d freq=%d duty=%d range=%d\n", gpio, freq, duty, range);

    gpioTerminate();

    return 0;
}

