#define TRIG 18
#define ECHO 23
#define LED 24

int main(void)
{
    struct gpiod_chip *chip;
    struct gpiod_line *trig, *echo, *led;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    trig = gpiod_chip_get_line(chip, TRIG);
    if (!trig) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(trig, "trig", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        exit(EXIT_FAILURE);
    }

    echo = gpiod_chip_get_line(chip, ECHO);
    if (!echo) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(echo, "echo");
    if (ret < 0) {
        perror("gpiod_line_request_input");
        exit(EXIT_FAILURE);
    }

    led = gpiod_chip_get_line(chip, LED);
    if (!led) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(led, "led", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        exit(EXIT_FAILURE);
    }

    while (1) {
        gpiod_line_set_value(trig, 1);
        usleep(10);
        gpiod_line_set_value(trig, 0);

        while (gpiod_line_get_value(echo) == 0);
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);

        while (gpiod_line_get_value(echo) == 1);
        clock_gettime(CLOCK_MONOTONIC, &end);

        double elapsed = (end.tv_sec - start.tv_sec);
        elapsed += (end.tv_nsec - start.tv_nsec) / 1000000000.0;
        double distance = (elapsed * 340.29) / 2;

        printf("Distance: %f cm\n", distance);

        if (distance < 10)
            gpiod_line_set_value(led, 1);
        else
            gpiod_line_set_value(led, 0);

        usleep(100000);
    }

    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_line_release(led);
    gpiod_chip_close(chip);

    return 0;
}

