{
    if (argc != 2)
    {
        printf("Usage: %s <duty cycle>\n", argv[0]);
        return 1;
    }

    int duty = atoi(argv[1]);
    if (duty < 0 || duty > 100)
    {
        printf("Duty cycle must be between 0 and 100\n");
        return 1;
    }

    if (gpioInitialise() < 0)
    {
        printf("Failed to initialise GPIO\n");
        return 1;
    }

    gpioSetMode(4, PI_OUTPUT);
    gpioSetMode(17, PI_OUTPUT);
    gpioSetMode(18, PI_OUTPUT);

    gpioSetPWMfrequency(4, 1000);
    gpioSetPWMfrequency(17, 1000);
    gpioSetPWMfrequency(18, 1000);

    gpioSetPWMrange(4, 100);
    gpioSetPWMrange(17, 100);
    gpioSetPWMrange(18, 100);

    gpioPWM(4, duty);
    gpioPWM(17, duty);
    gpioPWM(18, duty);

    while (1)
    {
        printf("Duty cycle: %d\n", duty);
        sleep(1);
    }

    gpioTerminate();
    return 0;
}

