#define DHT22_PIN 4
#define DHT22_MAX_TIMINGS 85

int data[5] = {0, 0, 0, 0, 0};

int dht22_read_data() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        fprintf(stderr, "Failed to open GPIO line\n");
        return 1;
    }

    ret = gpiod_line_request_output(line, "dht22", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        return 1;
    }

    gpiod_line_set_value(line, 0);
    usleep(18000);
    gpiod_line_set_value(line, 1);
    usleep(40);

    ret = gpiod_line_request_input(line, "dht22");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        return 1;
    }

    int last_state = 1;
    int counter = 0;
    int j = 0, i;
    for (i = 0; i < DHT22_MAX_TIMINGS; i++) {
        counter = 0;
        while (gpiod_line_get_value(line) == last_state) {
            counter++;
            usleep(1);
            if (counter == 255) {
                break;
            }
        }
        last_state = gpiod_line_get_value(line);

        if (counter == 255) {
            break;
        }

        if ((i >= 4) && (i % 2 == 0)) {
            data[j / 8] <<= 1;
            if (counter > 16) {
                data[j / 8] |= 1;
            }
            j++;
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    if ((j >= 40) &&
        (data[4] == ((data[0] + data[1] + data[2] + data[3]) & 0xFF))) {
        return 0;
    } else {
        return 1;
    }
}

int main(int argc, char *argv[]) {
    int i;
    for (i = 0; i < 3; i++) {
        if (dht22_read_data() == 0) {
            printf("Humidity = %d.%d %% Temperature = %d.%d *C\n",
                   data[0], data[1], data[2], data[3]);
        } else {
            printf("Failed to read data from DHT22\n");
        }
    }
    return 0;
}

