#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define CYCLE_TIME 60000000
#define CYCLE_COUNT 5

int main(int argc, char *argv[])
{
    int i;
    int gpio;
    int cycle_time;
    int cycle_count;
    int duty_cycle;
    int pulse_width;
    int period;
    int gpio_state;

    gpio = GPIO_PIN;
    cycle_time = CYCLE_TIME;
    cycle_count = CYCLE_COUNT;

    if (argc > 1)
    {
        gpio = atoi(argv[1]);
    }

    if (argc > 2)
    {
        cycle_time = atoi(argv[2]);
    }

    if (argc > 3)
    {
        cycle_count = atoi(argv[3]);
    }

    if (gpio < 0 || gpio > 31)
    {
        fprintf(stderr, "Invalid GPIO pin %d\n", gpio);
        return 1;
    }

    if (cycle_time < 1000000)
    {
        fprintf(stderr, "Invalid cycle time %d\n", cycle_time);
        return 1;
    }

    if (cycle_count < 1)
    {
        fprintf(stderr, "Invalid cycle count %d\n", cycle_count);
        return 1;
    }

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "gpioInitialise failed\n");
        return 1;
    }

    gpioSetMode(gpio, PI_OUTPUT);

    duty_cycle = 50;
    pulse_width = (duty_cycle * cycle_time) / 100;
    period = cycle_time;

    gpioSetPWMfrequency(gpio, 1000000);
    gpioSetPWMrange(gpio, 1000000);

    gpio_state = 0;

    for (i = 0; i < cycle_count; i++)
    {
        gpio_state = 1 - gpio_state;
        gpioWrite(gpio, gpio_state);
        gpioDelay(pulse_width);
        gpio_state = 1 - gpio_state;
        gpioWrite(gpio, gpio_state);
        gpioDelay(period - pulse_width);
    }

    gpioTerminate();

    return 0;
}

