int main(int argc, char *argv[])
{
    int i;
    int gpio[6] = {17, 18, 22, 23, 24, 25};
    int duty[6] = {0, 0, 0, 0, 0, 0};
    int range[6] = {100, 100, 100, 100, 100, 100};
    int freq[6] = {100, 100, 100, 100, 100, 100};

    if (gpioInitialise() < 0) return 1;

    for (i = 0; i < 6; i++)
    {
        gpioSetMode(gpio[i], PI_OUTPUT);
        gpioSetPWMfrequency(gpio[i], freq[i]);
        gpioSetPWMrange(gpio[i], range[i]);
        gpioPWM(gpio[i], duty[i]);
    }

    while (1)
    {
        for (i = 0; i < 6; i++)
        {
            duty[i] = (duty[i] + 1) % range[i];
            gpioPWM(gpio[i], duty[i]);
        }
        gpioDelay(50);
    }

    for (i = 0; i < 6; i++)
    {
        gpioSetPWMfrequency(gpio[i], 0);
        gpioSetPWMrange(gpio[i], 0);
        gpioPWM(gpio[i], 0);
    }

    gpioTerminate();
    return 0;
}

