#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIG 4
#define ECHO 17

int main(int argc, char *argv[])
{
    struct gpiod_chip *chip;
    struct gpiod_line *trig, *echo;
    struct gpiod_line_request req;
    struct gpiod_line_event event;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    req.request_type = GPIOD_LINE_REQUEST_EVENT_RISING_EDGE;
    req.consumer = "echo";
    req.lineoffsets[0] = TRIG;
    req.lineoffsets[1] = ECHO;
    req.lines = 2;
    req.flags = 0;

    ret = gpiod_chip_request_lines(chip, &req);
    if (ret < 0) {
        perror("gpiod_chip_request_lines");
        exit(EXIT_FAILURE);
    }

    trig = gpiod_chip_get_line(chip, TRIG);
    echo = gpiod_chip_get_line(chip, ECHO);

    ret = gpiod_line_request_event(trig, GPIOD_LINE_REQUEST_EVENT_RISING_EDGE);
    if (ret < 0) {
        perror("gpiod_line_request_event");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_event(echo, GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE);
    if (ret < 0) {
        perror("gpiod_line_request_event");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_event_wait(echo, &event);
    if (ret < 0) {
        perror("gpiod_line_event_wait");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_event_wait(trig, &event);
    if (ret < 0) {
        perror("gpiod_line_event_wait");
        exit(EXIT_FAILURE);
    }

    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);

    return 0;
}

