#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

int main(int argc, char *argv[])
{
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        fprintf(stderr, "Failed to get line\n");
        return 1;
    }

    ret = gpiod_line_request_output(line, "my-consumer", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line\n");
        return 1;
    }

    while (1) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line value\n");
            return 1;
        }

        printf("Line value set to 1\n");

        sleep(1);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line value\n");
            return 1;
        }

        printf("Line value set to 0\n");

        sleep(1);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_ADDR 0x10
#define I2C_BUS "/dev/i2c-1"

int main(int argc, char *argv[]) {
    int fd;
    char buf[2];
    int rc;
    int lux;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    rc = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (rc < 0) {
        perror("ioctl");
        exit(1);
    }

    while (1) {
        buf[0] = 0x00;
        rc = write(fd, buf, 1);
        if (rc != 1) {
            perror("write");
            exit(1);
        }

        rc = read(fd, buf, 2);
        if (rc != 2) {
            perror("read");
            exit(1);
        }

        lux = (buf[0] << 8) | buf[1];
        printf("%d\n", lux);

        sleep(0.5);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
