#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

#define BAUDRATE B9600
#define DEVICE "/dev/ttyS0"

int fd;

void cleanup(int signum) {
    close(fd);
    exit(0);
}

int main(int argc, char *argv[]) {
    struct termios options;
    char buf[100];
    int n;

    signal(SIGINT, cleanup);

    fd = open(DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror(DEVICE);
        exit(1);
    }

    tcgetattr(fd, &options);
    cfsetispeed(&options, BAUDRATE);
    cfsetospeed(&options, BAUDRATE);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_oflag &= ~OPOST;
    tcsetattr(fd, TCSANOW, &options);

    while (1) {
        n = read(fd, buf, 100);
        if (n < 0) {
            perror("read");
            exit(1);
        }
        if (n == 0) {
            fprintf(stderr, "device not responding\n");
            exit(1);
        }
        write(STDOUT_FILENO, buf, n);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIG_GPIO 17
#define ECHO_GPIO 18

int main(int argc, char *argv[])
{
    struct gpiod_chip *chip;
    struct gpiod_line *trig, *echo;
    struct gpiod_line_request req;
    struct gpiod_line_event event;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    req.request_type = GPIOD_LINE_REQUEST_EVENT_RISING_EDGE;
    req.flags = GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN;
    req.consumer = "echo";
    req.lineoffsets[0] = TRIG_GPIO;
    req.lineoffsets[1] = ECHO_GPIO;
    req.num_lines = 2;

    ret = gpiod_chip_request_lines(chip, &req);
    if (ret < 0) {
        perror("gpiod_chip_request_lines");
        exit(EXIT_FAILURE);
    }

    trig = gpiod_chip_get_line(chip, TRIG_GPIO);
    echo = gpiod_chip_get_line(chip, ECHO_GPIO);

    gpiod_line_request_event(trig, GPIOD_LINE_REQUEST_EVENT_RISING_EDGE);
    gpiod_line_request_event(echo, GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE);

    while (1) {
        ret = gpiod_line_event_wait(echo, &event);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            exit(EXIT_FAILURE);
        }

        gpiod_line_set_value(trig, 1);
        usleep(10);
        gpiod_line_set_value(trig, 0);

        ret = gpiod_line_event_wait(echo, &event);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            exit(EXIT_FAILURE);
        }

        printf("Distance: %d\n", event.ts.tv_nsec / 1000000);
        usleep(500000);
    }

    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);

    return 0;
}

