    int duty = 500;
    int range = 1000;
    int dc = 50;
    int pwm;

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    pwm = gpioSetPWMfrequency(gpio, freq);
    if (pwm < 0)
    {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        return 1;
    }

    pwm = gpioSetPWMrange(gpio, range);
    if (pwm < 0)
    {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        return 1;
    }

    while (1)
    {
        pwm = gpioPWM(gpio, duty);
        if (pwm < 0)
        {
            fprintf(stderr, "gpioPWM failed\n");
            return 1;
        }

        printf("Duty cycle: %d%%\n", dc);
        dc += 10;
        if (dc > 100)
        {
            dc = 0;
        }

        duty = (dc * range) / 100;

        gpioDelay(10000);
    }

    gpioTerminate();
    return 0;
}

