#define TRIG 4
#define ECHO 17
#define LED 18

int main(void)
{
    struct gpiod_chip *chip;
    struct gpiod_line *trig, *echo, *led;
    struct gpiod_line_request req;
    struct gpiod_line_event event;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    req.request_type = GPIOD_LINE_REQUEST_EVENT_RISING_EDGE;
    req.flags = GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN;
    req.consumer = "echo";

    trig = gpiod_chip_get_line(chip, TRIG);
    if (!trig) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request(trig, &req, 0);
    if (ret) {
        perror("gpiod_line_request");
        exit(EXIT_FAILURE);
    }

    echo = gpiod_chip_get_line(chip, ECHO);
    if (!echo) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request(echo, &req, 0);
    if (ret) {
        perror("gpiod_line_request");
        exit(EXIT_FAILURE);
    }

    led = gpiod_chip_get_line(chip, LED);
    if (!led) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request(led, &req, 0);
    if (ret) {
        perror("gpiod_line_request");
        exit(EXIT_FAILURE);
    }

    while (1) {
        ret = gpiod_line_event_wait(echo, &event);
        if (ret) {
            perror("gpiod_line_event_wait");
            exit(EXIT_FAILURE);
        }

        gpiod_line_set_value(led, 1);
        usleep(10000);
        gpiod_line_set_value(led, 0);
    }

    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_line_release(led);
    gpiod_chip_close(chip);

    return 0;
}

