    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open chip\n");
        exit(1);
    }

    config = gpiod_line_request_config_default(GPIO_PIN);
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_STATE;
    config.default_values[0] = 1;

    line = gpiod_chip_get_line(chip, GPIO_PIN_BCM);
    if (!line) {
        fprintf(stderr, "Failed to get line\n");
        exit(1);
    }

    ret = gpiod_line_request(line, &config, "my-line");
    if (ret < 0) {
        fprintf(stderr, "Failed to request line\n");
        exit(1);
    }

    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set line value\n");
        exit(1);
    }

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    while (1) {
        sleep(1);
    }

    return 0;
}

