#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <time.h>

int main(int argc, char *argv[])
{
    struct gpiod_chip *chip;
    struct gpiod_line *trigger, *echo;
    struct timespec start, end;
    int64_t diff;
    double distance;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open chip\n");
        return 1;
    }

    trigger = gpiod_chip_get_line(chip, 18);
    if (!trigger) {
        fprintf(stderr, "Failed to get trigger line\n");
        return 1;
    }

    echo = gpiod_chip_get_line(chip, 23);
    if (!echo) {
        fprintf(stderr, "Failed to get echo line\n");
        return 1;
    }

    if (gpiod_line_request_output(trigger, "trigger", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line\n");
        return 1;
    }

    if (gpiod_line_request_input(echo, "echo") < 0) {
        fprintf(stderr, "Failed to request echo line\n");
        return 1;
    }

    if (gpiod_line_set_value(trigger, 1) < 0) {
        fprintf(stderr, "Failed to set trigger line\n");
        return 1;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
        fprintf(stderr, "Failed to get start time\n");
        return 1;
    }

    if (gpiod_line_event_wait(echo, -1) < 0) {
        fprintf(stderr, "Failed to wait for echo line\n");
        return 1;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
        fprintf(stderr, "Failed to get end time\n");
        return 1;
    }

    diff = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
    distance = diff / 58.0;

    printf("Distance: %f cm\n", distance);

    gpiod_line_release(trigger);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);

    return 0;
}

