#define GPIO 18
#define FREQ 1000
#define DUTY 500

void sig_handler(int signo)
{
    if (signo == SIGINT)
    {
        printf("received SIGINT\n");
        gpioPWM(GPIO, 0);
        gpioTerminate();
        exit(0);
    }
}

int main(void)
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO, FREQ);
    gpioSetPWMrange(GPIO, 1000);

    signal(SIGINT, sig_handler);

    while (1)
    {
        gpioPWM(GPIO, DUTY);
        sleep(200);
    }

    return 0;
}

