#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_ADDR 0x68
#define I2C_BUS "/dev/i2c-1"

int main(int argc, char *argv[])
{
    int fd;
    int rc;
    uint8_t buf[14];

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    rc = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (rc < 0) {
        perror("ioctl");
        exit(1);
    }

    while (1) {
        rc = read(fd, buf, sizeof(buf));
        if (rc < 0) {
            perror("read");
            exit(1);
        }

        printf("accel: %d %d %d\n", buf[0] << 8 | buf[1], buf[2] << 8 | buf[3], buf[4] << 8 | buf[5]);
        printf("gyro: %d %d %d\n", buf[8] << 8 | buf[9], buf[10] << 8 | buf[11], buf[12] << 8 | buf[13]);

        sleep(1);
    }

    close(fd);

    return 0;
}

